import type * as Phaser from "phaser";
import { AUDIO } from "../config";

/** Sound effects in public/audio/ (generated by `npm run sfx`). */
export const SfxKey = {
  JUMP: "jump",
  LAND: "land",
  COIN: "coin",
  HURT: "hurt",
  DEATH: "death",
  CHECKPOINT: "checkpoint",
  LEVEL_COMPLETE: "levelComplete",
  MENU_SELECT: "menuSelect",
} as const;

export type SfxKeyValue = (typeof SfxKey)[keyof typeof SfxKey];

/**
 * Volume channels and mute (§2.4). Music has its own channel for the P2
 * chiptune loop. Phase 6 adds the settings screen and saves these.
 */
export const audioSettings = {
  sfxVolume: AUDIO.SFX_VOLUME as number,
  musicVolume: AUDIO.MUSIC_VOLUME as number,
  muted: AUDIO.MUTED as boolean,
};

export function loadSfx(scene: Phaser.Scene): void {
  for (const key of Object.values(SfxKey)) {
    scene.load.audio(key, `/audio/${key}.wav`);
  }
}

/** Play a sound effect on the SFX channel. Silently skips missing sounds. */
export function playSfx(scene: Phaser.Scene, key: SfxKeyValue): void {
  if (audioSettings.muted || audioSettings.sfxVolume <= 0) return;
  if (!scene.cache.audio.exists(key)) return;
  scene.sound.play(key, { volume: audioSettings.sfxVolume });
}
